"""Build the offline Phase 4 inspector from measured C++ CSV artifacts."""
import csv,json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
d=root/'Docs'/'Phase4'
data={k:list(csv.DictReader((d/f).open())) for k,f in [('response','frequency-response.csv'),('hold','global-crush-hold.csv')]}
html='''<!doctype html><meta charset="utf-8"><title>DISRUPTION Phase 4 DSP inspector</title><style>body{background:#121313;color:#ddd;font:16px system-ui;max-width:1100px;margin:40px auto}select{padding:8px;background:#222;color:#eee}svg{width:100%;background:#1b1d1e}path{fill:none;stroke-width:2}text{fill:#aaa;font:13px system-ui}</style><h1>DISRUPTION · Phase 4</h1><p>Developer-only measurements from the compiled C++ stages. BODY response uses a 0.001 amplitude sine; its saturation is level dependent. No plugin UI or audio runtime dependencies.</p><select id="stage"><option>TONE</option><option>BODY</option><option>Global CRUSH</option></select> <select id="rate"><option>44100</option><option selected>48000</option><option>88200</option><option>96000</option></select><p id="legend"></p><svg viewBox="0 0 1000 420" id="plot"></svg><p>Response: 10–18000 Hz logarithmic, −6 to +6 dB. Global CRUSH: 0–600 frames at 48 kHz; each amount has a distinct color. The hold plot uses a 437 Hz sine.</p><script>const data=DATA;const colors=['#47c5df','#7298fb','#999','#ffb357','#ff6038'];function draw(){let s=document.querySelector('#stage').value,r=document.querySelector('#rate').value,svg=document.querySelector('#plot');let groups=s==='TONE'?[-100,-50,0,50,100]:[0,25,50,75,100];document.querySelector('#rate').disabled=s==='Global CRUSH';document.querySelector('#legend').innerHTML=groups.map((a,i)=>`<span style="color:${colors[i]}">${a}%</span>`).join(' · ');let content='<path stroke="#555" d="M50 200H980 M50 20V390"/>';groups.forEach((a,i)=>{let rows=s==='Global CRUSH'?data.hold.filter(x=>+x.amount===a&&+x.frame<600):data.response.filter(x=>x.stage===s&&x.rate===r&&+x.amount===a);let path=rows.map((x,j)=>{let px=s==='Global CRUSH'?50+930*(+x.frame)/600:50+930*Math.log((+x.hz)/10)/Math.log(1800);let py=s==='Global CRUSH'?200-170*(+x.output):200-28*(+x.gain_db);return `${j?'L':'M'}${px.toFixed(2)},${py.toFixed(2)}`}).join(' ');content+=`<path stroke="${colors[i]}" d="${path}"/>`;});svg.innerHTML=content;}document.querySelectorAll('select').forEach(x=>x.onchange=draw);draw();</script>'''.replace('DATA',json.dumps(data))
(d/'DSP-Inspector.html').write_text(html,encoding='utf-8')
print(d/'DSP-Inspector.html')
